window.LISTEN_DATA = {"v":1,"kinds":{"s":"Short statements","r":"Questions and answers","d":"Short dialogs","c":"Conversations","k":"Short talks"},"items":[{"id":"L01","k":"s","L":[["M","The flight to San Antonio leaves at fourteen fifteen, not at four fifteen."]],"q":"When does the flight leave?","o":["At 2:15 in the afternoon","At 4:15 in the afternoon","At 4:50 in the morning","At 2:50 in the afternoon"],"a":0,"e":"In military time, fourteen fifteen (1415) is 2:15 p.m. The speaker corrects the mistake \"four fifteen\"."},{"id":"L02","k":"s","L":[["W","Only fifteen students passed the first test, but fifty passed the second one."]],"q":"How many students passed the second test?","o":["50","15","5","65"],"a":0,"e":"Fifty (stress on FIF-) passed the second test. Fifteen (stress on -TEEN) passed the first one."},{"id":"L03","k":"r","L":[["M","How long have you been stationed at this base?"]],"q":"Choose the best answer.","o":["Since last March.","At the main gate.","By bus, every morning.","About ten miles from here."],"a":0,"e":"\"How long\" asks about a period of time. \"Since last March\" gives the start of that period."},{"id":"L04","k":"d","L":[["W","Are you coming to the briefing at zero eight hundred?"],["M","I wouldn't miss it for the world."]],"q":"What does the man mean?","o":["He will certainly go to the briefing.","He does not want to go to the briefing.","He has never been to a briefing.","He thinks the briefing is too early."],"a":0,"e":"\"I wouldn't miss it for the world\" means \"I will certainly be there.\""},{"id":"L05","k":"d","L":[["M","Excuse me, where can I get my ID card renewed?"],["W","At the personnel office. It's on the second floor of Building Four, next to the post office."]],"q":"Where is the personnel office?","o":["On the second floor of Building 4","On the fourth floor of Building 2","Inside the post office","In front of Building 4"],"a":0,"e":"The woman says \"the second floor of Building 4, next to the post office\"."},{"id":"L06","k":"s","L":[["M","Before you clean your weapon, make sure it is unloaded."]],"q":"What must you do first?","o":["Check that the weapon is unloaded.","Clean the weapon.","Put on gloves.","Get a cleaning kit."],"a":0,"e":"\"Before you clean it, make sure it is unloaded\": the check comes first."},{"id":"L07","k":"r","L":[["W","Would you mind closing the window?"]],"q":"Choose the best answer.","o":["Not at all. I'll do it now.","Yes, it's a big window.","It was closed yesterday.","At the end of the hall."],"a":0,"e":"\"Would you mind...?\" is a polite request. \"Not at all\" means \"I don't mind\": the speaker agrees to help."},{"id":"L08","k":"d","L":[["M","Why didn't Sergeant Lopez come to physical training this morning?"],["W","He hurt his ankle playing basketball yesterday."]],"q":"Why did Sergeant Lopez miss physical training?","o":["He was injured.","He was on leave.","He overslept.","He was playing basketball."],"a":0,"e":"He hurt his ankle yesterday (an injury), so he could not train this morning. The basketball game was yesterday."},{"id":"L09","k":"s","L":[["W","The new truck is heavier than the old one, but it uses less fuel."]],"q":"What is true about the new truck?","o":["It uses less fuel than the old truck.","It is lighter than the old truck.","It uses more fuel than the old truck.","It weighs the same as the old truck."],"a":0,"e":"The new truck is heavier, but it uses less fuel."},{"id":"L10","k":"d","L":[["W","How did the inspection go?"],["M","It was a piece of cake."]],"q":"What does the man mean?","o":["The inspection was easy.","The inspection was canceled.","The inspection took a long time.","He ate during the inspection."],"a":0,"e":"\"A piece of cake\" means something very easy."},{"id":"L11","k":"s","L":[["M","The meeting has been moved from Tuesday to Thursday, at the same time."]],"q":"When is the meeting now?","o":["On Thursday","On Tuesday","On Tuesday and on Thursday","At a different time on Tuesday"],"a":0,"e":"\"Moved from Tuesday to Thursday\": the new day is Thursday, at the same time as before."},{"id":"L12","k":"r","L":[["M","Can I give you a hand with those boxes?"]],"q":"Choose the best answer.","o":["Thanks, that would be great.","Yes, I have two hands.","They are in the boxes.","I gave it to him yesterday."],"a":0,"e":"\"Give someone a hand\" means help them. The best answer accepts the help."},{"id":"L13","k":"d","L":[["W","Are you driving to Dallas this weekend?"],["M","I was going to, but my car is in the shop, so I'll take the bus."]],"q":"How will the man travel to Dallas?","o":["By bus","By car","By plane","He will not go."],"a":0,"e":"\"I was going to (drive), but my car is in the shop\" (being repaired), \"so I'll take the bus\"."},{"id":"L14","k":"s","L":[["W","We need two boxes of paper for each classroom, and there are six classrooms."]],"q":"How many boxes of paper do they need?","o":["Twelve","Six","Eight","Two"],"a":0,"e":"Two boxes for each of six classrooms: 2 x 6 = 12 boxes."},{"id":"L15","k":"d","L":[["M","I think the new schedule is much better."],["W","I couldn't agree more."]],"q":"What does the woman mean?","o":["She completely agrees with the man.","She does not agree with the man.","She wants a new schedule.","She cannot read the schedule."],"a":0,"e":"\"I couldn't agree more\" means \"I agree completely.\""},{"id":"L16","k":"s","L":[["M","If it rains tomorrow, the field exercise will start an hour later."]],"q":"What will happen if it rains?","o":["The exercise will begin later.","The exercise will be canceled.","The exercise will begin earlier.","The exercise will be moved indoors."],"a":0,"e":"If it rains, the exercise still takes place, but it starts an hour later."},{"id":"L17","k":"r","L":[["W","How often do you have English class?"]],"q":"Choose the best answer.","o":["Five days a week.","For two hours.","In Building 7.","With Mr. Davis."],"a":0,"e":"\"How often\" asks about frequency: five days a week."},{"id":"L18","k":"d","L":[["M","Have you seen my flashlight?"],["W","It's on the shelf, behind the first aid kit."]],"q":"Where is the flashlight?","o":["Behind the first aid kit","In the first aid kit","Under the shelf","In front of the first aid kit"],"a":0,"e":"The woman says it is \"on the shelf, behind the first aid kit\"."},{"id":"L19","k":"s","L":[["W","The jacket was eighty dollars, but I got it for half price."]],"q":"How much did the woman pay?","o":["$40","$80","$18","$160"],"a":0,"e":"Half of eighty dollars is forty dollars."},{"id":"L20","k":"d","L":[["M","Did the captain approve your leave request?"],["W","No, she turned it down."]],"q":"What happened to the woman's request?","o":["It was refused.","It was approved.","It was lost.","It was postponed."],"a":0,"e":"To \"turn down\" a request means to refuse it."},{"id":"L21","k":"s","L":[["M","The patient should take one tablet every eight hours."]],"q":"How many tablets should the patient take in one day?","o":["Three","One","Two","Eight"],"a":0,"e":"A day has 24 hours. One tablet every 8 hours makes 3 tablets a day."},{"id":"L22","k":"s","L":[["W","I'm afraid the library is closed until further notice."]],"q":"What does the woman say about the library?","o":["It is closed, and no reopening date has been given.","It will open again tomorrow morning.","It is open later than usual tonight.","It closed only a few minutes ago."],"a":0,"e":"\"Until further notice\" means until a new announcement is made: nobody knows yet when it will open."},{"id":"L23","k":"r","L":[["M","Do you know what time the dining facility opens?"]],"q":"Choose the best answer.","o":["At six thirty, I think.","Yes, the food is very good.","I ate there yesterday.","It's next to the gym."],"a":0,"e":"The question asks for a time, so the best answer gives one."},{"id":"L24","k":"d","L":[["W","Did you finish the report?"],["M","Almost. I just need to check the figures one more time."]],"q":"What does the man still have to do?","o":["Check the numbers in the report.","Write the whole report.","Give the report to the woman.","Draw the figures."],"a":0,"e":"\"The figures\" are the numbers in the report. He has almost finished: he only needs to check them."},{"id":"L25","k":"s","L":[["M","Private Kim arrived after the formation had already started."]],"q":"What happened?","o":["Private Kim was late for the formation.","Private Kim was early for the formation.","The formation started late.","The formation started without anyone."],"a":0,"e":"Past perfect: the formation had started before he arrived, so he was late."},{"id":"L26","k":"d","L":[["M","I'm not sure I can finish this by Friday."],["W","Don't worry. Take your time."]],"q":"What does the woman mean?","o":["There is no need to hurry.","He must finish it today.","She will finish it for him.","He should start again."],"a":0,"e":"\"Take your time\" means \"do not hurry\"."},{"id":"L27","k":"s","L":[["W","Go straight for two blocks, then turn left at the gas station. The clinic is on your right."]],"q":"Where should the listener turn left?","o":["At the gas station","At the clinic","After one block","At the first traffic light"],"a":0,"e":"\"Go straight for two blocks, then turn left at the gas station.\""},{"id":"L28","k":"d","L":[["M","Is Lieutenant Brown in her office?"],["W","She just stepped out. She'll be back in ten minutes."]],"q":"Where is Lieutenant Brown?","o":["She has left her office for a short time.","She is in her office.","She has gone home for the day.","She is on vacation."],"a":0,"e":"\"She just stepped out\" means she left for a short time. She will be back in ten minutes."},{"id":"L29","k":"r","L":[["W","What does your brother do?"]],"q":"Choose the best answer.","o":["He's a mechanic in the Air Force.","He's doing fine, thanks.","He does it every day.","He's twenty-five years old."],"a":0,"e":"\"What does he do?\" asks about a person's job."},{"id":"L30","k":"s","L":[["M","It's supposed to be cold and windy this afternoon, so bring your field jacket."]],"q":"What does the speaker advise?","o":["Bring warm clothing.","Stay inside all afternoon.","Bring an umbrella.","Wear light clothing."],"a":0,"e":"Cold and windy weather: the speaker tells the listener to bring a field jacket, which is warm clothing."},{"id":"L31","k":"s","L":[["W","The bus to the airport leaves every twenty minutes. The next one is at ten forty."]],"q":"When does the bus after the 10:40 bus leave?","o":["At 11:00","At 10:20","At 10:50","At 11:20"],"a":0,"e":"10:40 plus 20 minutes is 11:00."},{"id":"L32","k":"r","L":[["M","Could you tell me where the nearest ATM is?"]],"q":"Choose the best answer.","o":["There's one in front of the bank.","Yes, I could.","It costs three dollars.","I'll tell him tomorrow."],"a":0,"e":"The man is asking for a place, so the best answer gives a location. \"Yes, I could\" does not give the information."},{"id":"L33","k":"s","L":[["W","Sergeant Diaz used to smoke, but he quit last year."]],"q":"What do we know about Sergeant Diaz?","o":["He does not smoke now.","He smokes a lot now.","He started smoking last year.","He wants to start smoking."],"a":0,"e":"\"Used to\" means in the past but not now, and \"quit\" means stopped."},{"id":"L34","k":"d","L":[["M","Should I wear my dress uniform to the ceremony?"],["W","Yes. And make sure your shoes are polished."]],"q":"What will the man probably do?","o":["Wear his dress uniform and polish his shoes.","Wear his work uniform.","Buy new shoes.","Stay away from the ceremony."],"a":0,"e":"She says yes to the dress uniform and tells him to polish his shoes."},{"id":"L35","k":"s","L":[["M","I've been waiting for over an hour, and the mechanic still hasn't called me."]],"q":"How does the man probably feel?","o":["Impatient","Relaxed","Grateful","Sleepy"],"a":0,"e":"Waiting more than an hour with no news makes a person impatient."},{"id":"L36","k":"s","L":[["W","Hand in your homework on Monday at the latest."]],"q":"When must the students give their homework to the teacher?","o":["No later than Monday","After Monday","Only on Tuesday","Any time next week"],"a":0,"e":"\"At the latest\" means \"not after this time\"."},{"id":"L37","k":"d","L":[["M","Do you want to eat at the dining facility or go off base?"],["W","Let's stay here. It's raining too hard to drive."]],"q":"Where will they eat?","o":["On base","Off base","In the car","At a friend's house"],"a":0,"e":"\"Let's stay here\": they will not drive off base, so they will eat at the dining facility on base."},{"id":"L38","k":"s","L":[["M","The training was supposed to last three weeks, but it was extended by one more week."]],"q":"How long did the training last?","o":["Four weeks","Three weeks","Two weeks","One week"],"a":0,"e":"Three weeks, extended by one more week: four weeks."},{"id":"L39","k":"r","L":[["W","Whose helmet is this?"]],"q":"Choose the best answer.","o":["I think it's Corporal White's.","It's very heavy.","It's on the table.","He wears it every day."],"a":0,"e":"\"Whose\" asks who something belongs to."},{"id":"L40","k":"d","L":[["M","The colonel wants the plan by noon."],["W","Then we'd better get the ball rolling."]],"q":"What does the woman suggest?","o":["They should start working now.","They should play a game.","They should wait until noon.","They should call the colonel."],"a":0,"e":"\"Get the ball rolling\" means start an activity."},{"id":"L41","k":"s","L":[["W","The store is open from nine to five on weekdays, and from ten to two on Saturdays. It's closed on Sundays."]],"q":"When does the store close on Saturdays?","o":["At 2:00","At 5:00","At 10:00","It does not open on Saturdays."],"a":0,"e":"\"From ten to two on Saturdays\": it closes at two."},{"id":"L42","k":"d","L":[["M","Is this seat taken?"],["W","No, go ahead."]],"q":"What does the woman mean?","o":["The man can sit there.","Someone is sitting there.","The man should leave.","She will move to another seat."],"a":0,"e":"The seat is free, and \"go ahead\" gives permission: he can sit there."},{"id":"L43","k":"s","L":[["M","I'd have called you if I had known you were in town."]],"q":"What does the man mean?","o":["He did not know the listener was in town.","He called the listener.","He knew the listener was in town.","He will call the listener later."],"a":0,"e":"Third conditional: an unreal past. He did not know, so he did not call."},{"id":"L44","k":"r","L":[["W","How far is the firing range from here?"]],"q":"Choose the best answer.","o":["About three miles.","About three hours ago.","Three times a week.","Three rifles."],"a":0,"e":"\"How far\" asks about distance."},{"id":"L45","k":"d","L":[["M","I can't find the keys to the supply room."],["W","Did you check the drawer of my desk? I usually leave them there."]],"q":"Where does the woman usually leave the keys?","o":["In her desk drawer","In the supply room","On top of her desk","With the man"],"a":0,"e":"She says \"the drawer of my desk\"."},{"id":"L46","k":"s","L":[["W","Everyone except the new students has to attend the safety briefing."]],"q":"Who does NOT have to attend the briefing?","o":["The new students","The instructors","The officers","Everyone"],"a":0,"e":"\"Except\" leaves someone out: the new students do not have to attend."},{"id":"L47","k":"d","L":[["M","How was the movie?"],["W","I fell asleep halfway through."]],"q":"What does the woman imply?","o":["The movie was boring.","The movie was exciting.","She did not go to the movie.","She saw the movie twice."],"a":0,"e":"She fell asleep in the middle of the movie: she suggests that it was boring."},{"id":"L48","k":"s","L":[["M","The temperature dropped from seventy degrees to forty degrees overnight."]],"q":"How much did the temperature drop?","o":["Thirty degrees","Forty degrees","Seventy degrees","Eleven degrees"],"a":0,"e":"From 70 to 40 degrees: a drop of 30 degrees."},{"id":"L49","k":"r","L":[["M","Have you ever been to New York?"]],"q":"Choose the best answer.","o":["Yes, I went there two years ago.","Yes, I'm going there next week.","No, it's very big.","By plane."],"a":0,"e":"\"Have you ever...?\" asks about past experience. Only \"Yes, I went there two years ago\" talks about a past visit."},{"id":"L50","k":"d","L":[["W","I heard you got promoted. Congratulations!"],["M","Thanks. I can hardly believe it myself."]],"q":"How does the man feel?","o":["Surprised and happy","Angry","Disappointed","Worried about losing his job"],"a":0,"e":"\"I can hardly believe it\" shows surprise, and he thanks her: he is happy about the promotion."},{"id":"L51","k":"s","L":[["W","Please report to the orderly room at zero seven thirty."]],"q":"At what time should the listener report?","o":["7:30 a.m.","7:30 p.m.","7:03 a.m.","3:07 p.m."],"a":0,"e":"Zero seven thirty (0730) is 7:30 in the morning."},{"id":"L52","k":"r","L":[["M","Why don't we take a break?"]],"q":"Choose the best answer.","o":["Good idea. I'm tired.","Because it's broken.","I don't know why.","We took it yesterday."],"a":0,"e":"\"Why don't we...?\" is a suggestion, not a real question about a reason."},{"id":"L53","k":"d","L":[["W","Did you get the email about the new duty roster?"],["M","I haven't checked my email since this morning."]],"q":"What does the man mean?","o":["He has not seen the email yet.","He read the email this morning.","He wrote the new duty roster.","He never uses email."],"a":0,"e":"He has not checked his email since the morning, so he has not seen this email yet."},{"id":"L54","k":"s","L":[["M","Neither the captain nor the sergeant was at the meeting."]],"q":"Who was at the meeting?","o":["Neither of them","Only the captain","Only the sergeant","Both of them"],"a":0,"e":"\"Neither... nor...\" means not the captain and not the sergeant."},{"id":"L55","k":"d","L":[["M","Can you cover my shift on Saturday?"],["W","Sorry, my hands are tied. I'm on duty all weekend."]],"q":"What does the woman mean?","o":["She cannot help him.","She will work his shift.","She hurt her hands.","She is free on Saturday."],"a":0,"e":"\"My hands are tied\" means \"I am not free to do it\": she cannot help."},{"id":"L56","k":"s","L":[["M","The convoy leaves the base at twenty-two hundred, and the drive to the port takes four hours."]],"q":"At what time will the convoy reach the port?","o":["At 2:00 a.m.","At 10:00 p.m.","At 4:00 a.m.","At midnight"],"a":0,"e":"\"Twenty-two hundred\" (2200) is 10:00 p.m., and the drive \"takes four hours\". Four hours after 10:00 p.m. is 2:00 a.m."},{"id":"L57","k":"r","L":[["W","When's our next payday?"]],"q":"Choose the best answer.","o":["On the fifteenth.","For two weeks.","About two thousand dollars.","At the finance office."],"a":0,"e":"\"When\" asks about a time or a date. Only \"On the fifteenth\" gives the date of the next payday."},{"id":"L58","k":"d","L":[["W","Daylight saving time ended last night. Did you set your watch back an hour?"],["M","Oh no. It completely slipped my mind."]],"q":"What does the man mean?","o":["He forgot to change his watch.","He changed his watch last night.","He slipped and broke his watch.","He does not own a watch."],"a":0,"e":"\"It completely slipped my mind\" means \"I forgot all about it.\" He did not set his watch back."},{"id":"L59","k":"k","L":[["W","Attention, please. The eleven forty train to Washington will leave from Track Six today, not from Track Two. Because of work on the tracks, the train is running about fifteen minutes behind schedule. We apologize for the delay."]],"q":"Which track will the Washington train leave from?","o":["Track 6","Track 2","Track 11","Track 15"],"a":0,"e":"The train \"will leave from Track Six today, not from Track Two.\" Eleven forty is the time of the train, and fifteen minutes is the delay."},{"id":"L60","k":"s","L":[["M","I get thirty days of leave a year, and so far I've taken ten in June and eight in August."]],"q":"How many days of leave does the speaker have left this year?","o":["Twelve","Eighteen","Twenty","Thirty"],"a":0,"e":"He has taken 10 + 8 = 18 days. \"Thirty days\" minus 18 days leaves 12 days."},{"id":"L61","k":"r","L":[["M","Did you make it to the finance office before it closed?"]],"q":"Choose the best answer.","o":["Yes, with ten minutes to spare.","Yes, I made it myself.","It closes at five on weekdays.","About two hundred dollars."],"a":0,"e":"Here \"make it\" means \"get there in time\". \"Yes, with ten minutes to spare\" means the person answering got there ten minutes before the office closed."},{"id":"L62","k":"c","L":[["W","My flight gets in at nine forty tonight. Could you pick me up at the airport?"],["M","Sure, but I'm on duty until ten. Is ten thirty all right?"],["W","That's fine. It always takes a while to get my bags anyway."],["M","Great. I'll meet you outside the baggage claim area."]],"q":"At what time will the man pick the woman up?","o":["At 10:30 p.m.","At 9:40 p.m.","At 10:00 p.m.","At 10:40 p.m."],"a":0,"e":"The man is \"on duty until ten\", so he offers \"ten thirty\", and the woman says \"That's fine.\" Nine forty is when her flight lands."},{"id":"L63","k":"d","L":[["W","The hotel costs a hundred and twenty dollars a night, but the travel office will only pay ninety."],["M","So I'll have to pay the difference myself."]],"q":"How much will the man pay for each night?","o":["$30","$90","$120","$210"],"a":0,"e":"The hotel costs \"a hundred and twenty dollars a night\", and the travel office pays \"ninety\". The man pays the difference, $120 - $90 = $30."},{"id":"L64","k":"s","L":[["W","Out here, fresh water is delivered every other day, and the last delivery came yesterday."]],"q":"When will the next water delivery come?","o":["Tomorrow","Today","The day after tomorrow","Next week"],"a":0,"e":"\"Every other day\" means one day yes, one day no. The last delivery \"came yesterday\", so there is none today, and the next one comes tomorrow."},{"id":"L65","k":"r","L":[["W","My overtime pay finally came in, three months late. Can you believe it?"]],"q":"Choose the best answer.","o":["Well, better late than never.","Yes, I worked late last night.","No, I never work overtime.","About three months ago."],"a":0,"e":"\"Better late than never\" means it is good that something happens, even if it happens late. The pay came \"three months late\", so this answer fits."},{"id":"L66","k":"d","L":[["M","Did you catch your flight to Chicago last night?"],["W","Yes, but I got to the gate in the nick of time."]],"q":"What does the woman mean?","o":["She almost missed her flight.","She missed her flight.","She got to the gate very early.","She took a later flight."],"a":0,"e":"\"In the nick of time\" means at the last possible moment. She caught her flight, but she almost missed it."},{"id":"L67","k":"c","L":[["M","The mail room just called. Your package is there, and you have to pick it up today."],["W","What time does the mail room close?"],["M","At sixteen thirty, and it's sixteen ten now."],["W","Then I'd better leave right away. It's a fifteen-minute walk."]],"q":"What will the woman probably do next?","o":["Go to the mail room.","Call the mail room.","Wait until tomorrow.","Ask the man to get the package."],"a":0,"e":"The mail room closes at \"sixteen thirty\" (4:30 p.m.), and it is already \"sixteen ten\". She says, \"I'd better leave right away.\""},{"id":"L68","k":"s","L":[["W","We ordered ninety sleeping bags, but only seventy came in this morning. The rest will come next week."]],"q":"How many sleeping bags will come next week?","o":["Twenty","Seventy","Ninety","Seventeen"],"a":0,"e":"They \"ordered ninety\", but \"only seventy came in\". The rest is 90 - 70 = 20 sleeping bags."},{"id":"L69","k":"k","L":[["M","Hi, this is Sergeant Delgado from the transportation office, calling about your move. The movers can't come on Thursday after all. They'll pick up your household goods on Friday morning instead, starting at eight. Please call me back today to confirm that Friday works for you."]],"q":"What is the main point of the message?","o":["The pickup day has changed.","The move has been canceled.","Some furniture was damaged.","The movers will come on Thursday."],"a":0,"e":"The movers \"can't come on Thursday after all\" and will come \"on Friday morning instead\". The message gives a new day for the pickup."},{"id":"L70","k":"r","L":[["M","How much is a round-trip ticket to Boston?"]],"q":"Choose the best answer.","o":["It's ninety-five dollars.","About three hours each way.","Twice a day.","From Gate Four."],"a":0,"e":"\"How much\" asks about a price. Only \"ninety-five dollars\" is a price."},{"id":"L71","k":"d","L":[["M","So the cargo plane lands at zero seven hundred, and we finish unloading by noon?"],["W","Exactly. I'm glad we're on the same page."]],"q":"What does the woman mean?","o":["They agree about the plan.","They are reading the same report.","The plane will land at noon.","The plan is still not clear."],"a":0,"e":"\"We're on the same page\" means \"We understand the plan in the same way.\" She agrees with what the man said."},{"id":"L72","k":"s","L":[["M","The ferry has been delayed by two and a half hours, so it won't leave until seventeen hundred."]],"q":"When was the ferry supposed to leave?","o":["At 2:30 p.m.","At 5:00 p.m.","At 7:30 p.m.","At 2:30 a.m."],"a":0,"e":"\"Seventeen hundred\" (1700) is 5:00 p.m., the new time. Two and a half hours earlier is 2:30 p.m."},{"id":"L73","k":"c","L":[["W","Captain Brennan, I'd like to take leave from the tenth to the twentieth of next month."],["M","We have an inspection on the eighteenth. Can you be back before then?"],["W","Yes, sir. I can come back on the seventeenth."],["M","All right. Change the dates on your form, and I'll sign it."]],"q":"When will the woman come back from leave?","o":["On the 17th","On the 18th","On the 20th","On the 10th"],"a":0,"e":"The inspection is \"on the eighteenth\", so she says, \"I can come back on the seventeenth.\" The captain agrees."},{"id":"L74","k":"r","L":[["M","Excuse me, do you have the time?"]],"q":"Choose the best answer.","o":["Sure. It's twenty to five.","Yes, I have all afternoon.","It took about an hour.","Every day at five."],"a":0,"e":"\"Do you have the time?\" is a polite way to ask what time it is. Only \"It's twenty to five\" (4:40) gives the time."},{"id":"L75","k":"d","L":[["W","It's already nineteen thirty, and all the equipment is packed for tomorrow."],["M","Great. Then let's call it a day."]],"q":"What does the man suggest?","o":["They should stop working for today.","They should pack more equipment.","They should call someone for help.","They should work through the night."],"a":0,"e":"\"Let's call it a day\" means \"Let's stop working for today.\" It is late, and the job is done."},{"id":"L76","k":"k","L":[["W","Good evening, everyone. Tomorrow we move to the training area. Breakfast is from zero four thirty to zero five fifteen, and the buses leave from behind Building Nine at zero five thirty sharp. The drive takes about two hours, and the first exercise begins as soon as we arrive."]],"q":"At about what time will the first exercise begin?","o":["At about 7:30 a.m.","At about 5:30 a.m.","At about 7:15 a.m.","At about 4:30 a.m."],"a":0,"e":"The buses leave at \"zero five thirty\" (5:30 a.m.), and \"the drive takes about two hours\". The exercise begins \"as soon as we arrive\", at about 7:30 a.m."},{"id":"L77","k":"s","L":[["W","The tires we ordered were delivered on Monday, the day before yesterday."]],"q":"What day is it today?","o":["Wednesday","Tuesday","Monday","Saturday"],"a":0,"e":"\"The day before yesterday\" was Monday, so yesterday was Tuesday. Today is Wednesday."},{"id":"L78","k":"r","L":[["W","Everyone's waiting for you at the restaurant. How soon can you get here?"]],"q":"Choose the best answer.","o":["In about ten minutes.","Ten minutes ago.","Every ten minutes.","For ten minutes."],"a":0,"e":"\"How soon\" asks how much time will pass before something happens. Only \"In about ten minutes\" answers that."},{"id":"L79","k":"c","L":[["W","How many trucks do we need to take the tents out to the field?"],["M","We have forty-eight tents, and each truck holds twelve, so we need four."],["W","The motor pool can only give us three until Thursday."],["M","Then one of them will make two trips. It'll take longer, but we'll get it done."]],"q":"How will they move all the tents?","o":["One truck will make two trips.","They will wait until Thursday.","They will move only thirty-six tents.","They will borrow a fourth truck."],"a":0,"e":"They need four trucks, but the motor pool \"can only give us three\". So the man says \"one of them will make two trips\"."},{"id":"L80","k":"d","L":[["M","It's almost five o'clock. Can you still send me the delivery schedule today?"],["W","Sorry, I can't. I'll send it first thing in the morning."]],"q":"When will the woman send the schedule?","o":["Early tomorrow morning","Before five o'clock today","Tomorrow afternoon","Later tonight"],"a":0,"e":"\"First thing in the morning\" means early the next morning, before anything else. She \"can't\" send it today."},{"id":"L81","k":"s","L":[["M","This truck is supposed to get an oil change every three thousand miles, and it's gone almost five thousand since the last one."]],"q":"What does the speaker mean?","o":["The truck should have had an oil change already.","The truck had an oil change a short time ago.","The truck needs an oil change every 5,000 miles.","The truck has gone only 3,000 miles since its last change."],"a":0,"e":"The oil should be changed \"every three thousand miles\", but the truck has gone \"almost five thousand\" since the last change. The change is late."},{"id":"L82","k":"r","L":[["W","Do I need an appointment for sick call, or can I just walk in?"]],"q":"Choose the best answer.","o":["You can just walk in, but get there early.","I walked there yesterday afternoon.","Yes, I feel much better now.","It was a very short appointment."],"a":0,"e":"The woman asks about two choices, an appointment or \"just walk in\". The best reply picks one of them: she can just walk in."},{"id":"L83","k":"d","L":[["M","Have they fixed the washing machines in the barracks yet?"],["W","Two of them are still out of order, so you might have to wait."]],"q":"What does the woman mean?","o":["Two machines are still not working.","All the machines have been fixed.","The machines must be used in order.","Two new machines have been ordered."],"a":0,"e":"\"Out of order\" means not working. Two machines are \"still out of order\", so they have not been fixed yet."},{"id":"L84","k":"k","L":[["W","Good morning. Here is today's weather for the base. Thick fog will stay with us until about ten o'clock, so drive slowly and use your low beams. This afternoon will be sunny and warm, with a high of seventy-eight degrees. Thunderstorms will move in after nine tonight, so put away any loose equipment before you go home."]],"q":"What will the weather be like this afternoon?","o":["Sunny and warm","Foggy and cool","Stormy and windy","Cloudy with light rain"],"a":0,"e":"The report says \"this afternoon will be sunny and warm\". The fog is in the morning, and the storms come tonight."},{"id":"L85","k":"s","L":[["W","We've run out of toner for the printer, and the new order won't arrive until Thursday."]],"q":"What does the speaker say about the toner?","o":["There is none left.","It arrived on Thursday.","Someone ran out to buy more.","There is plenty of it."],"a":0,"e":"To \"run out of\" something means to use all of it. There is no toner now, and the new order \"won't arrive until Thursday\"."},{"id":"L86","k":"c","L":[["W","I need a vehicle this afternoon to pick up twenty boxes of uniforms from the warehouse."],["M","All the trucks are out, but you can take the pickup."],["W","Will twenty boxes fit in the back?"],["M","They should. Just take a tarp to cover them."],["W","A tarp? But it's sunny outside."],["M","Not for long. It's supposed to rain later this afternoon."]],"q":"Why does the man tell the woman to take a tarp?","o":["Rain is expected later today.","The boxes will not fit in the back.","The sun is very strong today.","The road to the warehouse is muddy."],"a":0,"e":"The man wants the boxes covered because \"it's supposed to rain later this afternoon\"."},{"id":"L87","k":"r","L":[["W","How was the food at the new dining facility?"]],"q":"Choose the best answer.","o":["Better than I expected.","I drove there with a friend.","Around noon, I think.","It's across from the clinic."],"a":0,"e":"\"How was the food?\" asks for an opinion. \"Better than I expected\" gives an opinion about the food."},{"id":"L88","k":"d","L":[["W","You look pale. Are you all right?"],["M","I'm a little under the weather, that's all."]],"q":"What does the man mean?","o":["He feels a little sick.","He got wet in the rain.","He does not like the weather.","He has been working outside."],"a":0,"e":"\"Under the weather\" means a little sick. It has nothing to do with rain or the weather outside."},{"id":"L89","k":"s","L":[["W","Unless you've completed the safety course, you're not allowed to drive the forklift."]],"q":"Who may drive the forklift?","o":["People who have completed the safety course","People who are taking the safety course now","People who have not taken the safety course","Anyone who has a driver's license"],"a":0,"e":"\"Unless you've completed the safety course, you're not allowed\" means that only people who have finished the course may drive it."},{"id":"L90","k":"r","L":[["M","Who's in charge of the office while Major Ramirez is away?"]],"q":"Choose the best answer.","o":["Captain Chen is.","Until next Friday.","On the second floor.","About ten people."],"a":0,"e":"\"Who\" asks about a person. \"Captain Chen is\" names the person in charge."},{"id":"L91","k":"d","L":[["M","How much do I owe you for the coffee and the muffin?"],["W","It's on the house today."]],"q":"What does the woman mean?","o":["The man does not have to pay.","The man can pay her tomorrow.","The food was made at her house.","The coffee costs more today."],"a":0,"e":"\"On the house\" means free, paid for by the business. The man does not have to pay."},{"id":"L92","k":"c","L":[["M","Sergeant Miller, the doctor at sick call told me to rest in my room until tomorrow."],["W","All right. Did she give you a note for the first sergeant?"],["M","Yes, I have it right here."],["W","Good. Drop it off at the orderly room on your way back, and I'll let the platoon know."]],"q":"What will the man probably do next?","o":["Take the note to the orderly room.","Go back to sick call for more tests.","Tell the platoon that he is sick.","Return to work for the afternoon."],"a":0,"e":"The woman tells him to \"drop it off at the orderly room on your way back\". She will tell the platoon herself."},{"id":"L93","k":"s","L":[["W","My computer is at the help desk for repairs, so I'll be using Sergeant Haddad's until Friday."]],"q":"Whose computer will the speaker use until Friday?","o":["Sergeant Haddad's computer","Her own computer","A computer from the help desk","A brand-new computer"],"a":0,"e":"Her own computer is \"at the help desk for repairs\", so she will use \"Sergeant Haddad's\" until Friday."},{"id":"L94","k":"k","L":[["M","Listen up. Before you start work in the motor pool today, here are three safety rules. Wear your gloves and safety glasses at all times on the shop floor. Never stand under a vehicle that is held up only by a jack. And if you see fuel or oil on the floor, clean it up right away or report it to me."]],"q":"What should workers do if they see fuel or oil on the floor?","o":["Clean it up right away or report it","Put on their gloves and safety glasses","Move the vehicle off the jack","Leave the shop floor at once"],"a":0,"e":"The third rule is \"if you see fuel or oil on the floor, clean it up right away or report it to me\"."},{"id":"L95","k":"r","L":[["W","What's the weather supposed to be like this weekend?"]],"q":"Choose the best answer.","o":["Sunny on Saturday, but rainy on Sunday.","Whether you like it or not.","I'd like that very much.","Yes, it was a nice weekend."],"a":0,"e":"\"What's the weather supposed to be like?\" asks for a forecast. Only \"Sunny on Saturday, but rainy on Sunday\" describes the weather."},{"id":"L96","k":"d","L":[["W","The neighbors had another loud party last night. It went on until two in the morning."],["M","That's the last straw. I'm going to talk to the building manager today."]],"q":"What does the man mean?","o":["He will not accept the noise any longer.","He thinks it was the last party.","He wants to join the next party.","He spoke to the manager last night."],"a":0,"e":"\"That's the last straw\" means \"I can't accept this any more.\" After \"another loud party\", he is going to complain to the building manager."},{"id":"L97","k":"s","L":[["M","While the kitchen is being painted, lunch will be served in the gym instead of the dining facility."]],"q":"Where will lunch be served while the kitchen is being painted?","o":["In the gym","In the dining facility","In the kitchen","In the barracks"],"a":0,"e":"Lunch will be served \"in the gym instead of the dining facility\" while the kitchen is being painted."},{"id":"L98","k":"c","L":[["M","Any news on our order for the new radios?"],["W","Bad news, I'm afraid. The supply office lost the paperwork, so it was never sent."],["M","Oh, no. So we're back to square one. I'll fill out the forms again this afternoon."]],"q":"What happened to the radio order?","o":["It was never sent because the paperwork was lost.","It was sent, but the radios were the wrong kind.","It was sent to the wrong supply office.","It was canceled because the radios cost too much."],"a":0,"e":"The woman says \"the supply office lost the paperwork, so it was never sent\". They are \"back to square one\": they must start again."},{"id":"L99","k":"r","L":[["M","You've already signed for your room key, haven't you?"]],"q":"Choose the best answer.","o":["Yes, I did that this morning.","I signed up for the course.","By the front door, I think.","My room is very clean."],"a":0,"e":"The tag \"haven't you?\" asks the listener to confirm. \"Yes, I did that this morning\" confirms that the key was signed for."},{"id":"L100","k":"d","L":[["M","Do you think they'll cancel the outdoor ceremony because of the heat?"],["W","I'd be surprised if they did. It's only supposed to be in the low eighties."]],"q":"What does the woman mean?","o":["The ceremony will probably take place.","The ceremony will probably be canceled.","The weather will be dangerously hot.","She was surprised it was canceled."],"a":0,"e":"\"I'd be surprised if they did\" means she does not expect them to cancel it. A temperature in \"the low eighties\" is not dangerously hot."},{"id":"L101","k":"s","L":[["M","You must wear hearing protection in the generator room, even if you're only going in for a minute."]],"q":"When must people wear hearing protection in the generator room?","o":["Every single time they go in","Only when they stay a long time","Only during their first minute inside","Only when a generator is being repaired"],"a":0,"e":"\"Even if you're only going in for a minute\" means there is no exception. Hearing protection is needed every time."},{"id":"L102","k":"k","L":[["W","Hi, this is Specialist Okafor at the supply room. The cold weather boots you ordered have finally come in. You can pick them up any weekday between one and four in the afternoon. Please bring the old pair you're turning in, along with your copy of the order form."]],"q":"What should the listener bring?","o":["The old boots and the order form","A cold weather jacket and gloves","The receipt for the new boots","A pair of thick winter socks"],"a":0,"e":"The caller says \"bring the old pair you're turning in, along with your copy of the order form\". The old pair means the old boots."},{"id":"L103","k":"r","L":[["W","Could you keep an eye on the phones while I run down to the mailroom?"]],"q":"Choose the best answer.","o":["Sure, I'll watch them for you.","My eyes are fine, thanks.","I ran there this morning.","It's next to the mailroom."],"a":0,"e":"\"Keep an eye on\" means watch something for someone. \"Sure, I'll watch them for you\" accepts the request."},{"id":"L104","k":"d","L":[["M","Can I take the van to the training area this afternoon?"],["W","Not unless you want to push it. The battery's dead."]],"q":"What does the woman mean?","o":["The van cannot be driven right now.","The man should push the van there.","The van needs more fuel first.","She will drive the man there herself."],"a":0,"e":"\"Not unless you want to push it\" is a joke that means no. The van will not start because \"the battery's dead\"."},{"id":"L105","k":"c","L":[["W","Have you heard when we're moving into the new barracks?"],["M","It's still up in the air. The building hasn't passed its final inspection yet."],["W","That's too bad. I was hoping to move in before winter."],["M","So was I. I'll tell you as soon as I hear anything."]],"q":"When will they move into the new barracks?","o":["The date has not been decided yet.","They will move in before winter.","They will move in right after winter.","They have already moved in."],"a":0,"e":"\"Up in the air\" means not decided yet. The building \"hasn't passed its final inspection\", so there is no moving date."},{"id":"L106","k":"s","L":[["W","I'd rather study in the library than in my room, because my roommate plays loud music all evening."]],"q":"Where does the speaker prefer to study?","o":["In the library","In her room","In a classroom","In the music room"],"a":0,"e":"\"I'd rather study in the library than in my room\" means she prefers the library. Her room is too noisy."},{"id":"L107","k":"r","L":[["M","What did you get on the listening test?"]],"q":"Choose the best answer.","o":["I got an eighty-five.","I got it at the bookstore.","I got there at eight.","I took it on Monday."],"a":0,"e":"\"What did you get on the listening test?\" asks about the score. \"An eighty-five\" is a score."},{"id":"L108","k":"d","L":[["M","Do you know why the soccer game was canceled?"],["W","Beats me. The weather is perfect."]],"q":"What does the woman mean?","o":["She does not know the reason.","Her team lost the game.","She canceled the game herself.","The weather was too bad to play."],"a":0,"e":"\"Beats me\" means \"I have no idea.\" She does not know why the game was canceled."},{"id":"L109","k":"k","L":[["M","Listen up. Tomorrow's fitness test will start at zero six hundred on the track behind the gym. You will do push-ups first, then sit-ups, and you will finish with a two-mile run. If you have an injury, report to me before the test begins."]],"q":"What is the last part of the test?","o":["A two-mile run","Sit-ups","Push-ups","A medical check"],"a":0,"e":"The speaker says \"push-ups first, then sit-ups\", and \"you will finish with a two-mile run\"."},{"id":"L110","k":"s","L":[["M","The instructor didn't collect the tests until every student had finished."]],"q":"When did the instructor collect the tests?","o":["After all the students had finished","Before any student had finished","When the first student finished","In the middle of the test"],"a":0,"e":"\"Didn't collect the tests until every student had finished\" means the instructor waited for everyone to finish."},{"id":"L111","k":"r","L":[["W","Excuse me, which way is the language lab?"]],"q":"Choose the best answer.","o":["Down this hall, on your left.","It opens at seven thirty.","Yes, I study there.","It was built last year."],"a":0,"e":"\"Which way\" asks for directions. \"Down this hall, on your left\" tells her where to go."},{"id":"L112","k":"c","L":[["W","Hi. I'd like to check out these three books, please."],["M","Sure. May I see your library card?"],["W","Here you are. How long can I keep them?"],["M","Three weeks. But this one is a reference book, so it can't leave the library."]],"q":"How many books can the woman borrow?","o":["Two","Three","One","None"],"a":0,"e":"She wants three books, but one is a reference book that \"can't leave the library\". She can borrow the other two."},{"id":"L113","k":"d","L":[["W","We're getting pizza tonight. Do you want to come?"],["M","I'd love to, but I really need to hit the books."]],"q":"What does the man mean?","o":["He has to study.","He will come later.","He has to return some books.","He does not like pizza."],"a":0,"e":"\"Hit the books\" means study hard. He would like to go, but he has to study."},{"id":"L114","k":"s","L":[["W","The post office is on Oak Street, between the bank and the barber shop, and right across from the bowling alley."]],"q":"What is across from the post office?","o":["The bowling alley","The bank","The barber shop","The bus station"],"a":0,"e":"The post office is \"between the bank and the barber shop\" and \"right across from the bowling alley\"."},{"id":"L115","k":"r","L":[["M","How many push-ups can you do in two minutes?"]],"q":"Choose the best answer.","o":["About sixty, on a good day.","Every morning before work.","For two minutes.","Yes, I can do them."],"a":0,"e":"\"How many\" asks for a number. \"About sixty\" is the number of push-ups."},{"id":"L116","k":"d","L":[["W","Did you finish the ten-mile march, Ramirez?"],["M","Yes, but I couldn't keep up with the others."]],"q":"What does the man mean?","o":["He was slower than the others.","He was faster than the others.","He did not finish the march.","He got up earlier than the others."],"a":0,"e":"\"Couldn't keep up with the others\" means he could not go as fast as they did. He finished, but more slowly."},{"id":"L117","k":"c","L":[["M","Are you going to the gym after class?"],["W","I was planning to, but it's closed for repairs until Monday."],["M","Then let's go running on the track. It's open until dark."],["W","Good idea. I'll meet you there at seventeen hundred."]],"q":"What will the man and the woman probably do after class?","o":["Go running on the track","Work out at the gym","Help repair the gym","Rest until Monday"],"a":0,"e":"The gym is \"closed for repairs until Monday\", so the man suggests the track, and the woman agrees to meet him there."},{"id":"L118","k":"s","L":[["M","Before the radio class on Friday, every student must know the phonetic alphabet by heart."]],"q":"What must the students do before the radio class?","o":["Memorize the phonetic alphabet.","Bring a copy of the phonetic alphabet.","Practice using the radio.","Have their hearts checked."],"a":0,"e":"To \"know something by heart\" means to know it from memory. The students must memorize the alphabet before the class."},{"id":"L119","k":"k","L":[["W","When you plan a route on a map, look at the scale first. On our training maps, one centimeter equals two hundred fifty meters. As a rule of thumb, a soldier with a full pack covers about four kilometers an hour on a flat road, but much less in the hills. So always add extra time if your route goes uphill."]],"q":"According to the speaker, how fast does a soldier with a full pack walk on a flat road?","o":["About 4 kilometers an hour","About 250 meters an hour","About 1 kilometer an hour","About 40 kilometers an hour"],"a":0,"e":"A \"rule of thumb\" is a simple general guide. The speaker's rule is that a soldier with a full pack \"covers about four kilometers an hour on a flat road\"."},{"id":"L120","k":"r","L":[["W","Who won the basketball game last night?"]],"q":"Choose the best answer.","o":["The Navy team, by six points.","I won't play tonight.","At the base gym, I think.","It started at seven."],"a":0,"e":"\"Who won?\" asks for the winner. \"The Navy team\" is the only answer that names one."},{"id":"L121","k":"d","L":[["M","Are you going to apply for the instructor course in Texas?"],["W","I already did, but it's a long shot."]],"q":"What does the woman mean?","o":["She does not expect to be accepted.","The course lasts a very long time.","Texas is very far from here.","She has not sent her application yet."],"a":0,"e":"\"A long shot\" is something with little chance of success. She has applied, but she does not think she will be accepted."},{"id":"L122","k":"s","L":[["W","Unless you score at least seventy on the progress test, you'll have to repeat the unit."]],"q":"What will happen to a student who scores 65?","o":["The student will repeat the unit.","The student will go on to the next unit.","The student will leave the school.","The student will change instructors."],"a":0,"e":"\"Unless you score at least seventy\" means \"if you score less than seventy\". Sixty-five is less than seventy, so the student must repeat the unit."},{"id":"L123","k":"c","L":[["W","Excuse me, I'm looking for the education center. I have a placement test at nine."],["M","It's in Building Twenty-two. Go straight down this road and turn right at the flagpole."],["W","Is it far? I don't have a car."],["M","Not really, it's about a ten-minute walk. Look for the brick building across from the parking lot."]],"q":"Where is the education center?","o":["Across from the parking lot","Next to the flagpole","Behind the parking lot","In Building 20"],"a":0,"e":"The man says it is in Building Twenty-two, \"the brick building across from the parking lot\"."},{"id":"L124","k":"r","L":[["M","Could you repeat the last question, please?"]],"q":"Choose the best answer.","o":["Of course. I'll read it again.","Yes, it was the last one.","I answered it last week.","It was a hard question."],"a":0,"e":"\"Could you repeat...?\" is a polite request. \"Of course. I'll read it again\" agrees to do it."},{"id":"L125","k":"d","L":[["M","Did Private Chen pass the land navigation test?"],["W","Yes, with flying colors."]],"q":"What does the woman mean?","o":["He did very well on the test.","He barely passed the test.","He did not take the test.","He carried a flag during the test."],"a":0,"e":"To pass \"with flying colors\" means to pass easily, with an excellent result."},{"id":"L126","k":"k","L":[["M","Hello, Corporal Haddad, this is Mister Novak, your reading instructor. Tomorrow's class will be in Room Fourteen instead of Room Four, because the projector in our room is broken. Please tell the other students in your group. See you at zero eight hundred."]],"q":"Why did the speaker call?","o":["To tell Corporal Haddad about a room change","To cancel tomorrow's class","To ask Corporal Haddad to fix the projector","To ask for the other students' phone numbers"],"a":0,"e":"The main message is that tomorrow's class \"will be in Room Fourteen instead of Room Four\"."},{"id":"L127","k":"s","L":[["M","The gym gets too crowded after seventeen hundred, so I usually work out before breakfast."]],"q":"When does the speaker usually work out?","o":["Before breakfast","After breakfast","After 5 p.m.","After 7 p.m."],"a":0,"e":"After seventeen hundred (5 p.m.) the gym is \"too crowded\", so he works out \"before breakfast\"."},{"id":"L128","k":"r","L":[["W","How was the obstacle course this morning?"]],"q":"Choose the best answer.","o":["Harder than I expected.","Behind the barracks, I think.","Twice a week, usually.","At six in the morning."],"a":0,"e":"\"How was...?\" asks how something went. \"Harder than I expected\" describes the experience."},{"id":"L129","k":"d","L":[["M","Where were you? We waited for you for half an hour."],["W","Sorry. I was reading in the library and lost track of time."]],"q":"Why was the woman late?","o":["She did not notice how late it was.","She lost her watch in the library.","She got lost on the way.","She could not find her book."],"a":0,"e":"To \"lose track of time\" means to stop noticing the time. She was busy reading and did not see how late it was."},{"id":"L130","k":"c","L":[["M","According to the map, the bridge is about two kilometers north of here."],["W","Are you sure? I thought it was south of here."],["M","Let me look again. Oh, you're right. I was holding the map upside down."]],"q":"In which direction is the bridge?","o":["To the south","To the north","To the east","To the west"],"a":0,"e":"The man first says \"north\", but then he sees he was \"holding the map upside down\". The woman was right: the bridge is to the south."},{"id":"L131","k":"s","L":[["W","My husband had our son's bicycle fixed at the shop on Pine Street."]],"q":"Who fixed the bicycle?","o":["A worker at the shop","The speaker's husband","The speaker's son","The speaker"],"a":0,"e":"\"Had our son's bicycle fixed\" means the husband asked someone else to do the work. A worker at the shop fixed it."},{"id":"L132","k":"r","L":[["W","Captain Haddad is on another line right now. Would you like to hold?"]],"q":"Choose the best answer.","o":["Sure, I don't mind waiting.","No, it isn't very heavy.","He called me an hour ago.","Yes, he's a good captain."],"a":0,"e":"On the phone, \"Would you like to hold?\" means \"Do you want to wait on the line?\" The best reply agrees to wait."},{"id":"L133","k":"d","L":[["W","Are you going to buy those leather boots you tried on?"],["M","I'd like to, but they cost an arm and a leg."]],"q":"What does the man mean?","o":["The boots are very expensive.","The boots hurt his leg.","He has already bought the boots.","The boots are too big for him."],"a":0,"e":"\"Cost an arm and a leg\" means cost a lot of money. He would like the boots, but they are very expensive."},{"id":"L134","k":"k","L":[["W","Attention, passengers on flight seven twenty-two to Norfolk. The fog is too thick for aircraft to take off safely, so all departures are on hold. We now expect boarding to begin at sixteen fifty, about forty minutes later than planned. Please stay near Gate nine and listen for further announcements."]],"q":"When is boarding now expected to begin?","o":["At 4:50 p.m.","At 4:10 p.m.","At 6:50 p.m.","At 5:30 p.m."],"a":0,"e":"The new boarding time is \"sixteen fifty\" (1650), which is 4:50 p.m. The forty-minute delay is already included in that time."},{"id":"L135","k":"s","L":[["M","After twenty years at sea, Chief Novak is used to sleeping in a narrow bunk."]],"q":"What does the speaker say about Chief Novak?","o":["He is accustomed to sleeping in a narrow bunk.","He slept in a narrow bunk in the past, but not now.","He finds it hard to sleep in a narrow bunk.","He has spent two years at sea."],"a":0,"e":"\"Is used to sleeping\" means he is accustomed to it, so it is normal for him now. \"Used to sleep\", without \"is\", would describe a past habit."},{"id":"L136","k":"r","L":[["M","Are you ready to order, or do you need a few more minutes?"]],"q":"Choose the best answer.","o":["I'm ready. I'll have the chicken soup.","It was delicious, thank you.","About ten minutes ago.","Yes, I ordered it online."],"a":0,"e":"The waiter asks \"Are you ready to order?\" The best reply says \"I'm ready\" and gives the order."},{"id":"L137","k":"c","L":[["M","Excuse me, my flight to Atlanta was canceled. Is there another flight today?"],["W","There's one at six forty this evening, but it's already full. I can put you on the first flight tomorrow morning."],["M","I guess I don't have much choice. What time does it leave?"],["W","At six fifteen. And since the cancellation was our fault, we'll pay for your hotel tonight."]],"q":"When will the man fly to Atlanta?","o":["Tomorrow at 6:15 a.m.","Today at 6:40 p.m.","Today at 6:15 p.m.","Tomorrow at 6:40 a.m."],"a":0,"e":"The flight at \"six forty this evening\" is full, so the woman offers \"the first flight tomorrow morning\" at \"six fifteen\". The man accepts."},{"id":"L138","k":"d","L":[["M","Dinner was great. Let me get the check this time."],["W","That's nice of you, but let's go Dutch tonight."]],"q":"What does the woman suggest?","o":["They should each pay for their own meal.","The man should pay for both meals.","They should eat at a Dutch restaurant.","She should pay for both meals."],"a":0,"e":"\"Let's go Dutch\" means that each person pays for his or her own meal. She thanks him but does not let him pay for both."},{"id":"L139","k":"s","L":[["M","We didn't receive Colonel Okafor's message until our radio was repaired the next morning."]],"q":"When did they receive the message?","o":["After the radio was repaired","Before the radio stopped working","While the radio was being repaired","They never received it"],"a":0,"e":"They \"didn't receive\" the message \"until our radio was repaired\", so they got it only after the repair, the next morning."},{"id":"L140","k":"r","L":[["W","Can I pay for this with a credit card?"]],"q":"Choose the best answer.","o":["Sure. We accept all major cards.","It's a birthday card for my aunt.","You paid for it last week.","It's on sale for $20."],"a":0,"e":"The customer asks \"Can I pay for this with a credit card?\" The answer \"We accept all major cards\" means yes."},{"id":"L141","k":"d","L":[["W","Sorry, I have another call coming in. Can we finish this conversation later?"],["M","No problem. Let's touch base tomorrow morning."]],"q":"What does the man suggest?","o":["They should talk again tomorrow morning.","They should go to the base together tomorrow.","She should not answer the other call.","He should call her back in a few minutes."],"a":0,"e":"\"Let's touch base tomorrow morning\" means \"let's contact each other again tomorrow morning\". It has nothing to do with a military base."},{"id":"L142","k":"c","L":[["W","I'd like to return this sweater. It's too small for my son."],["M","Do you have the receipt?"],["W","No, I don't. It was a gift from my sister."],["M","Then I can't give you a refund, but you can exchange it for a larger size."]],"q":"What will the woman probably do next?","o":["Exchange the sweater for a larger one","Get her money back","Exchange the sweater for a smaller one","Give the sweater back to her sister"],"a":0,"e":"With no receipt she cannot get \"a refund\", but the man says she \"can exchange it for a larger size\", which is what her son needs."},{"id":"L143","k":"s","L":[["W","Sergeant Miller isn't answering his phone. He must have left it in his car again."]],"q":"What does the speaker think?","o":["Sergeant Miller probably left his phone in his car.","Sergeant Miller has to leave his phone in his car.","Sergeant Miller should keep his phone in his car.","Sergeant Miller is talking on the phone in his car."],"a":0,"e":"\"He must have left it in his car\" is a guess about the past: the speaker is almost sure he did. It is not an obligation."},{"id":"L144","k":"r","L":[["M","Excuse me, is this the gate for flight five eighteen to Denver?"]],"q":"Choose the best answer.","o":["No, that flight leaves from Gate 12.","It lands at 5:18.","I've been to Denver twice.","It takes about two hours."],"a":0,"e":"The man asks if he is at the right gate. Only \"No, that flight leaves from Gate 12\" answers that question."},{"id":"L145","k":"k","L":[["M","Attention all hands. A storm is expected to reach the port tomorrow afternoon, so the ship will leave at zero six hundred instead of fourteen hundred. Shore leave ends at twenty-one hundred tonight. All personnel who are ashore must be back on board by that time."]],"q":"Why will the ship leave earlier than planned?","o":["A storm will reach the port tomorrow afternoon.","A storm has already damaged the port.","All shore leave has been canceled.","The port will close for repairs tomorrow."],"a":0,"e":"The ship will leave at 0600 instead of 1400 because \"a storm is expected to reach the port tomorrow afternoon\"."},{"id":"L146","k":"d","L":[["M","We're having a barbecue on Sunday. Can you and your husband come?"],["W","I'd love to, but can I take a rain check? My parents are visiting this weekend."]],"q":"What does the woman mean?","o":["She would like to come another time instead.","She will come if it does not rain.","She will bring her parents to the barbecue.","She needs to check the weather first."],"a":0,"e":"\"Can I take a rain check?\" is a polite way to say \"I can't come this time, but please ask me again.\" It has nothing to do with rain."},{"id":"L147","k":"s","L":[["M","After its engine failed, the fishing boat was towed back to the harbor by a Navy patrol boat."]],"q":"What happened?","o":["A Navy boat pulled the fishing boat to the harbor.","The fishing boat pulled a Navy boat to the harbor.","The Navy boat's engine failed near the harbor.","The fishing boat got back to the harbor on its own."],"a":0,"e":"The fishing boat \"was towed\" (pulled) \"by a Navy patrol boat\", so the Navy boat did the pulling. The engine that failed was the fishing boat's."},{"id":"L148","k":"r","L":[["M","Bravo Two, this is Bravo One, radio check. How do you read me? Over."]],"q":"Choose the best answer.","o":["Loud and clear.","I read it last night.","Slowly, one word at a time.","Mostly newspapers and novels."],"a":0,"e":"In a radio check, \"How do you read me?\" asks how well you hear the caller. \"Loud and clear\" means the signal is strong and easy to understand."},{"id":"L149","k":"c","L":[["M","Do you want to take the kids to the beach on Saturday?"],["W","I'd rather go to the lake. The beach is so crowded on weekends that we can never find a place to sit."],["M","Good point. And the kids can go fishing there."],["W","Great. I'll pack a picnic lunch."]],"q":"Where will they probably go on Saturday?","o":["To the lake","To the beach","To a swimming pool","To a fishing store"],"a":0,"e":"The woman says \"I'd rather go to the lake\" because the beach is \"so crowded\", and the man agrees: \"Good point.\""},{"id":"L150","k":"d","L":[["W","Did you remember to reserve a table for tonight?"],["M","No, but I should have. The earliest table they have now is at nine thirty."]],"q":"What does the man mean?","o":["He is sorry he did not reserve a table.","He reserved a table earlier today.","He will reserve a table tomorrow.","The restaurant has no tables left tonight."],"a":0,"e":"\"No, but I should have\" shows regret: he did not reserve a table, and now the earliest one is at nine thirty."},{"id":"L151","k":"s","L":[["W","I'm sorry, but we can't cash this check unless you show us some photo identification."]],"q":"What does the speaker mean?","o":["The check can be cashed only with a photo ID.","The check cannot be cashed at this bank.","A photo ID is not necessary.","The bank needs a photo of the check."],"a":0,"e":"\"Unless\" means \"if not\": if the customer does not show \"photo identification\", the bank will not cash the check."},{"id":"L152","k":"r","L":[["W","How do you usually spend your weekends?"]],"q":"Choose the best answer.","o":["I go hiking with my kids.","About fifty dollars.","On Saturdays and Sundays.","Usually by car."],"a":0,"e":"\"How do you usually spend your weekends?\" asks what you do in your free time. Here \"spend\" is about time, not money."},{"id":"L153","k":"d","L":[["M","If I borrow ten thousand dollars for a car, how much will I pay each month?"],["W","I'd need to check a few details, but a ballpark figure would be three hundred dollars a month."]],"q":"What does the woman mean?","o":["The monthly payment of $300 is only an estimate.","The monthly payment will be exactly $300.","The bank will lend him only $300.","He must pay $10,000 each month."],"a":0,"e":"A \"ballpark figure\" is a rough number. She still needs to \"check a few details\", so $300 is only an estimate."},{"id":"L154","k":"c","L":[["W","I'd like to mail this package to my daughter in Germany."],["M","Express mail takes three days. Regular mail costs half as much, but it takes about two weeks."],["W","Her birthday is on Friday, so I'll send it express."],["M","All right. That comes to forty-two dollars."]],"q":"Why does the woman choose express mail?","o":["She wants the package to arrive by Friday.","It costs half as much as regular mail.","Regular mail does not go to Germany.","Her daughter asked for express mail."],"a":0,"e":"Regular mail is cheaper but takes about two weeks. The birthday \"is on Friday\", so she pays more for the faster service."},{"id":"L155","k":"k","L":[["W","Eagle Two, this is Base. Your pickup point has changed, so do not go to the bridge. Move to the old water tower, one mile north of the bridge. The helicopter will pick you up there at fifteen thirty. Base out."]],"q":"Where should Eagle Two go?","o":["To the old water tower","To the bridge","One mile south of the bridge","To the helicopter base"],"a":0,"e":"The message says \"do not go to the bridge\". The new pickup point is \"the old water tower, one mile north of the bridge\"."}]};
